~~~go
func fizzBuzz(limit int) []string {
    out := make([]string, 0, max(limit, 0))
    for n := 1; n <= limit; n++ {
        switch {
        case n%15 == 0:
            out = append(out, "FizzBuzz")
        case n%3 == 0:
            out = append(out, "Fizz")
        case n%5 == 0:
            out = append(out, "Buzz")
        default:
            out = append(out, strconv.Itoa(n))
        }
    }
    return out
}
